CREATE TABLE IF NOT EXISTS editorial_drafts (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, material_id UUID NOT NULL, title TEXT, hook TEXT, body TEXT, context TEXT, closing TEXT, cta TEXT, hashtags JSONB DEFAULT '[]', observations TEXT, status VARCHAR(50) DEFAULT 'draft', created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
